cuda_src = r"""
#include <torch/extension.h>
#include <c10/cuda/CUDAStream.h>
#include <c10/cuda/CUDAGuard.h>
#include <cuda_runtime.h>
#include <cute/tensor.hpp>
#include <type_traits>
#include <vector>

using namespace cute;

// Single fused LayerNorm kernel.
// Grid: (splits, rows). Each block reduces a contiguous chunk of one row,
// atomically accumulates partial sums, synchronizes across the splits of its
// row (all blocks are guaranteed co-resident because the grid is clamped to
// the occupancy limit), then normalizes its chunk with the final mean/rstd.
template <typename T, typename VecT, int TPB>
__global__ void layernorm_rows_kernel(
    const T* __restrict__ X,
    const T* __restrict__ W,
    const T* __restrict__ B,
    T* __restrict__ Y,
    double* __restrict__ d_sum,
    double* __restrict__ d_sumsq,
    int*   __restrict__ d_count,
    int64_t Ne,     // number of VecT elements per row
    int64_t chunk,  // VecT elements per split (multiple of TPB)
    int64_t N,      // number of scalars per row
    float eps)
{
  constexpr int V = (int)(sizeof(VecT) / sizeof(T));

  const int row    = blockIdx.y;
  const int split  = blockIdx.x;
  const int nsplit = gridDim.x;
  const int tid    = threadIdx.x;

  const VecT* xrow = reinterpret_cast<const VecT*>(X + (int64_t)row * N);
  VecT*       yrow = reinterpret_cast<VecT*>(Y + (int64_t)row * N);

  // CuTe global tensors (row views)
  Tensor gX = make_tensor(make_gmem_ptr(xrow), make_shape(Ne), make_stride(Int<1>{}));
  Tensor gY = make_tensor(make_gmem_ptr(yrow), make_shape(Ne), make_stride(Int<1>{}));
  Tensor gW = make_tensor(make_gmem_ptr(reinterpret_cast<const VecT*>(W)),
                          make_shape(Ne), make_stride(Int<1>{}));
  Tensor gB = make_tensor(make_gmem_ptr(reinterpret_cast<const VecT*>(B)),
                          make_shape(Ne), make_stride(Int<1>{}));

  const int64_t begin = (int64_t)split * chunk;
  int64_t end = begin + chunk;
  if (end > Ne) end = Ne;

  __shared__ double rs[TPB];
  __shared__ double rq[TPB];
  __shared__ double s_mean, s_rstd;

  // ---- Phase 1: partial reduction (double accumulation for stability) ----
  double s = 0.0, q = 0.0;
  for (int64_t i = begin + tid; i < end; i += TPB) {
    VecT v = gX(i);
    if constexpr (V == 4) {
      double x0 = (double)v.x;
      double x1 = (double)v.y;
      double x2 = (double)v.z;
      double x3 = (double)v.w;
      s += (x0 + x1) + (x2 + x3);
      q += (x0 * x0 + x1 * x1) + (x2 * x2 + x3 * x3);
    } else {
      double x0 = (double)v;
      s += x0;
      q += x0 * x0;
    }
  }

  // Block tree reduction
  rs[tid] = s;
  rq[tid] = q;
  __syncthreads();
  #pragma unroll
  for (int off = TPB / 2; off > 0; off >>= 1) {
    if (tid < off) {
      rs[tid] += rs[tid + off];
      rq[tid] += rq[tid + off];
    }
    __syncthreads();
  }

  // Cross-split accumulation + synchronization for this row
  if (tid == 0) {
    atomicAdd(&d_sum[row], rs[0]);
    atomicAdd(&d_sumsq[row], rq[0]);
    __threadfence();
    atomicAdd(&d_count[row], 1);
    while (atomicAdd(&d_count[row], 0) < nsplit) { }
    __threadfence();
    double sum  = __ldcg(d_sum + row);
    double sumq = __ldcg(d_sumsq + row);
    double mean = sum / (double)N;
    double var  = sumq / (double)N - mean * mean;
    if (var < 0.0) var = 0.0;
    s_mean = mean;
    s_rstd = rsqrt(var + (double)eps);
  }
  __syncthreads();

  const float fmean = (float)s_mean;
  const float frstd = (float)s_rstd;

  // ---- Phase 2: normalize + optional affine ----
  for (int64_t i = begin + tid; i < end; i += TPB) {
    VecT xv = gX(i);
    VecT yv;
    if constexpr (V == 4) {
      float wx = 1.0f, wy = 1.0f, wz = 1.0f, ww = 1.0f;
      float bx = 0.0f, by = 0.0f, bz = 0.0f, bw = 0.0f;
      if (W != nullptr) {
        float4 wv = gW(i);
        wx = wv.x; wy = wv.y; wz = wv.z; ww = wv.w;
      }
      if (B != nullptr) {
        float4 bv = gB(i);
        bx = bv.x; by = bv.y; bz = bv.z; bw = bv.w;
      }
      yv.x = ((float)xv.x - fmean) * frstd * wx + bx;
      yv.y = ((float)xv.y - fmean) * frstd * wy + by;
      yv.z = ((float)xv.z - fmean) * frstd * wz + bz;
      yv.w = ((float)xv.w - fmean) * frstd * ww + bw;
    } else {
      float w0 = 1.0f, b0 = 0.0f;
      if (W != nullptr) w0 = (float)gW(i);
      if (B != nullptr) b0 = (float)gB(i);
      yv = ((float)xv - fmean) * frstd * w0 + b0;
    }
    gY(i) = yv;
  }
}

template <typename VecT>
static void launch_layernorm(
    const float* X, const float* W, const float* B, float* Y,
    double* d_sum, double* d_sumsq, int* d_count,
    int64_t N, int64_t R, float eps, int numSMs, cudaStream_t stream)
{
  constexpr int TPB = 256;
  constexpr int V = (int)(sizeof(VecT) / sizeof(float));
  const int64_t Ne = N / V;

  auto kfn = layernorm_rows_kernel<float, VecT, TPB>;
  int bpsm = 0;
  cudaError_t oerr = cudaOccupancyMaxActiveBlocksPerMultiprocessor(&bpsm, kfn, TPB, 0);
  TORCH_CHECK(oerr == cudaSuccess, "occupancy query failed: ", cudaGetErrorString(oerr));
  if (bpsm < 1) bpsm = 1;

  // Clamp grid so all blocks are co-resident (required for the spin sync).
  int64_t maxResident = (int64_t)bpsm * (int64_t)numSMs;
  int64_t S = maxResident / R;
  if (S < 1) S = 1;
  int64_t Smax = (Ne + TPB - 1) / TPB;
  if (Smax < 1) Smax = 1;
  if (S > Smax) S = Smax;

  int64_t chunk = (Ne + S - 1) / S;
  chunk = ((chunk + TPB - 1) / TPB) * (int64_t)TPB;
  int64_t Seff = (Ne + chunk - 1) / chunk;

  dim3 grid((unsigned)Seff, (unsigned)R);
  dim3 block(TPB);
  kfn<<<grid, block, 0, stream>>>(X, W, B, Y, d_sum, d_sumsq, d_count,
                                  Ne, chunk, N, eps);
}

torch::Tensor layernorm_forward(torch::Tensor x,
                                c10::optional<torch::Tensor> weight,
                                c10::optional<torch::Tensor> bias,
                                std::vector<int64_t> normalized_shape,
                                double eps)
{
  TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  const int64_t ndim = x.dim();
  const int64_t nn = (int64_t)normalized_shape.size();
  TORCH_CHECK(nn >= 1, "normalized_shape must be non-empty");
  TORCH_CHECK(ndim >= nn, "x.dim() must be >= len(normalized_shape)");

  int64_t N = 1;
  for (int64_t i = 0; i < nn; ++i) {
    TORCH_CHECK(x.size(ndim - nn + i) == normalized_shape[i],
                "x trailing dims must match normalized_shape");
    N *= normalized_shape[i];
  }
  TORCH_CHECK(N > 0, "normalized numel must be > 0");
  const int64_t R = x.numel() / N;
  TORCH_CHECK(R >= 1 && R <= 65535, "rows out of supported range");

  const c10::cuda::CUDAGuard device_guard(x.device());
  auto x_c = x.contiguous();

  torch::Tensor w_c, b_c;
  const float* w_ptr = nullptr;
  const float* b_ptr = nullptr;
  if (weight.has_value() && weight->defined()) {
    TORCH_CHECK(weight->is_cuda() && weight->scalar_type() == at::kFloat, "bad weight");
    TORCH_CHECK(weight->numel() == N, "weight numel mismatch");
    w_c = weight->contiguous();
    w_ptr = w_c.data_ptr<float>();
  }
  if (bias.has_value() && bias->defined()) {
    TORCH_CHECK(bias->is_cuda() && bias->scalar_type() == at::kFloat, "bad bias");
    TORCH_CHECK(bias->numel() == N, "bias numel mismatch");
    b_c = bias->contiguous();
    b_ptr = b_c.data_ptr<float>();
  }

  auto y = torch::empty_like(x_c);

  auto f64 = torch::TensorOptions().dtype(torch::kFloat64).device(x_c.device());
  auto i32 = torch::TensorOptions().dtype(torch::kInt32).device(x_c.device());
  auto d_sum   = torch::zeros({R}, f64);
  auto d_sumsq = torch::zeros({R}, f64);
  auto d_count = torch::zeros({R}, i32);

  int dev = x_c.get_device();
  int numSMs = 0;
  cudaDeviceGetAttribute(&numSMs, cudaDevAttrMultiProcessorCount, dev);
  TORCH_CHECK(numSMs > 0, "could not query SM count");

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

  const float* X = x_c.data_ptr<float>();
  float* Y = y.data_ptr<float>();

  bool aligned16 = ((N & 3) == 0) &&
      ((reinterpret_cast<uintptr_t>(X) & 15) == 0) &&
      ((reinterpret_cast<uintptr_t>(Y) & 15) == 0) &&
      (w_ptr == nullptr || (reinterpret_cast<uintptr_t>(w_ptr) & 15) == 0) &&
      (b_ptr == nullptr || (reinterpret_cast<uintptr_t>(b_ptr) & 15) == 0);

  if (aligned16) {
    launch_layernorm<float4>(X, w_ptr, b_ptr, Y,
                             d_sum.data_ptr<double>(),
                             d_sumsq.data_ptr<double>(),
                             d_count.data_ptr<int>(),
                             N, R, (float)eps, numSMs, stream);
  } else {
    launch_layernorm<float>(X, w_ptr, b_ptr, Y,
                            d_sum.data_ptr<double>(),
                            d_sumsq.data_ptr<double>(),
                            d_count.data_ptr<int>(),
                            N, R, (float)eps, numSMs, stream);
  }

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "layernorm kernel launch failed: ",
              cudaGetErrorString(err));
  return y;
}
"""

_ext = load_inline(
    name="cute_layernorm_ext",
    cpp_sources=cpp_decl,
    cuda_sources=cuda_src,
    functions=["layernorm_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/root/cutegen_test/cutegen/cutlass/include",
        "/root/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Layer Normalization implemented with a single fused custom CuTe/CUDA kernel.
    """
    def __init__(self, normalized_shape):
        super().__init__()
        if isinstance(normalized_shape, int):
            normalized_shape = (normalized_shape,)
        self.normalized_shape = tuple(int(d) for d in normalized_shape)
        self.eps = 1e-5
        self.weight = nn.Parameter(torch.ones(self.normalized_shape))
        self.bias = nn.Parameter(torch.zeros(self.normalized_shape))
        self._ext = _ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.layernorm_forward(
            x,
            self.weight,
            self.bias,
            list(self.normalized_shape),
            self.eps,
        )

